#!/usr/bin/env python3
"""Generate five standalone local-first H5 apps; no external assets, analytics or ads."""
import json, html, pathlib
ROOT=pathlib.Path(__file__).resolve().parents[1]
NEEDS=json.loads((ROOT/'intake/2026-10-23.json').read_text())['needs']
CSS=r'''<style>
:root{--bg:#f5faf8;--ink:#153344;--muted:#59717b;--teal:#0a756e;--line:#d5e5e1;--warn:#fff7e7}
*{box-sizing:border-box}body{margin:0;background:var(--bg);color:var(--ink);font:15px/1.55 system-ui,-apple-system,'Segoe UI',sans-serif}
main.app{max-width:1140px;margin:0 auto;padding:30px 18px 55px}.eyebrow{font-size:12px;color:var(--teal);font-weight:900;letter-spacing:1.2px;text-transform:uppercase}h1{font-size:clamp(30px,4vw,45px);line-height:1.13;letter-spacing:-1.2px;margin:9px 0}h2{font-size:21px;margin:0 0 13px}h3{font-size:17px;margin:16px 0 8px}.lead{color:var(--muted);font-size:17px;max-width:780px}.grid{display:grid;grid-template-columns:minmax(0,1.08fr) minmax(310px,.92fr);gap:20px;margin-top:24px;align-items:start}
.panel,.prose{background:white;border:1px solid var(--line);border-radius:17px;padding:22px;box-shadow:0 8px 24px #0a604006;min-width:0}.prose{margin-top:20px;box-shadow:none}.prose p,.prose li{color:#506b76}.fields{display:grid;grid-template-columns:repeat(2,minmax(0,1fr));gap:12px}.fields.three{grid-template-columns:repeat(3,minmax(0,1fr))}label{display:flex;flex-direction:column;gap:5px;color:#3b606b;font-size:13px;font-weight:750}input,select,textarea{width:100%;min-width:0;border:1px solid #b9cfca;border-radius:9px;padding:10px 11px;font:inherit;color:#163947;background:white}input:focus,textarea:focus,select:focus{outline:3px solid #c3eee4;border-color:var(--teal)}textarea{min-height:80px}button{border:1px solid #b6d5ce;border-radius:9px;padding:10px 13px;background:#e8f6f2;color:#08695f;font:inherit;font-size:14px;font-weight:800;cursor:pointer}button.primary{background:var(--teal);border-color:var(--teal);color:white}.actions{display:flex;gap:9px;flex-wrap:wrap;margin:17px 0}.metrics{display:grid;grid-template-columns:repeat(2,minmax(0,1fr));gap:11px}.metric{background:#ecf7f4;padding:13px;border-radius:11px}.metric small{display:block;color:#55727b}.metric strong{display:block;font-size:clamp(20px,2.5vw,27px);overflow-wrap:anywhere}.note{font-size:13px;color:#5b7480}.warning{background:var(--warn);padding:13px;border-left:3px solid #d4a04d;font-size:13px;margin-top:17px}.row{border:1px solid var(--line);padding:12px;border-radius:11px;margin:10px 0}.row strong{display:block}.row small{color:#647f87}.row button{float:right;padding:5px 9px}.status{min-height:22px;color:#08796c;font-size:13px}.tablewrap{overflow-x:auto}table{border-collapse:collapse;width:100%;font-size:13px}td,th{padding:9px;border-bottom:1px solid var(--line);text-align:left;white-space:nowrap}th{color:#496c75}.good{color:#007d61}.bad{color:#b85c35}
@media(max-width:780px){.grid{grid-template-columns:1fr}}@media(max-width:480px){.fields,.fields.three{grid-template-columns:1fr}main.app{padding:22px 12px}.panel,.prose{padding:17px}}
@media print{body{background:white}.actions,.warning,.eyebrow,.prose,.status{display:none!important}.panel{box-shadow:none}.grid{display:block}}
</style>'''
SHARED_JS=r'''
const $=id=>document.getElementById(id), n=id=>Number($(id).value), usd=v=>Number(v).toLocaleString('en-US',{style:'currency',currency:'USD',maximumFractionDigits:2});
const esc=s=>String(s??'').replace(/[&<>"']/g,c=>({'&':'&amp;','<':'&lt;','>':'&gt;','"':'&quot;',"'":'&#39;'}[c]));
const nonneg=(...v)=>v.every(x=>Number.isFinite(x)&&x>=0);
function localRead(k,d){try{return JSON.parse(localStorage.getItem(k))??d}catch{return d}}
function localWrite(k,d){try{localStorage.setItem(k,JSON.stringify(d));return true}catch{if($('status'))$('status').textContent='Browser storage unavailable. Export your work.';return false}}
function csv(rows){return '\ufeff'+rows.map(r=>r.map(x=>'"'+String(x??'').replaceAll('"','""')+'"').join(',')).join('\r\n')}
function download(data,name,type='text/csv;charset=utf-8'){let u=URL.createObjectURL(new Blob([data],{type})),a=document.createElement('a');a.href=u;a.download=name;document.body.appendChild(a);a.click();a.remove();setTimeout(()=>URL.revokeObjectURL(u),7000)}
function dayDiff(a,b){return Math.round((Date.parse(b+'T12:00:00Z')-Date.parse(a+'T12:00:00Z'))/86400000)}
'''
def f(label,id,value='',typ='number',attrs=''):
 return f'<label>{html.escape(label)}<input id="{id}" type="{typ}" value="{html.escape(str(value),quote=True)}" {attrs}></label>'
def app(i,body,script,article):
 d=NEEDS[i]; title=d['headline'];desc=d['description'];schema={'@context':'https://schema.org','@type':'SoftwareApplication','name':d['name'],'applicationCategory':'BusinessApplication','operatingSystem':'Web','description':desc,'offers':{'@type':'Offer','price':'0','priceCurrency':'USD'}}
 markup=f'''<!doctype html><html lang="en"><head><meta charset="utf-8"><meta name="viewport" content="width=device-width,initial-scale=1"><title>{html.escape(title)} | Worklane Tools</title><meta name="description" content="{html.escape(desc,quote=True)}"><meta property="og:title" content="{html.escape(title,quote=True)}"><meta property="og:description" content="{html.escape(desc,quote=True)}"><meta property="og:type" content="website"><script type="application/ld+json">{json.dumps(schema,ensure_ascii=False)}</script>{CSS}</head><body><main class="app"><div class="eyebrow">Free local-first browser tool · No account</div><h1>{html.escape(title)}</h1><p class="lead">{html.escape(desc)}</p>{body}<section class="prose">{article}</section></main><script>{SHARED_JS}\n{script}</script></body></html>'''
 path=ROOT/'apps'/d['slug'];path.mkdir(parents=True,exist_ok=True);(path/'index.html').write_text(markup,encoding='utf-8')

app(0,r'''<div class="grid"><section class="panel"><h2>Shared utility bill</h2><div class="fields">
<label>Billing period start<input id="start" type="date" value="2026-10-01"></label><label>Billing period end (inclusive)<input id="end" type="date" value="2026-10-31"></label>
<label>Total water bill ($)<input id="bill" type="number" min="0" step="0.01" value="180"></label><label>Fixed base charges ($)<input id="fixed" type="number" min="0" step="0.01" value="35"></label></div>
<h3>Units served by the meter</h3><p class="note">Occupant-days = number of residents × days included in the billing period. This is an assumption, not measured usage.</p><div id="units"></div><div class="actions"><button id="add">Add unit</button><button id="export">Export allocation CSV</button></div><p class="status" id="status" role="status"></p></section>
<section class="panel"><h2>Compare allocation methods</h2><div class="metrics"><div class="metric"><small>Bill total</small><strong id="total">$0</strong></div><div class="metric"><small>Billing days</small><strong id="days">0</strong></div></div><div class="tablewrap"><table><thead><tr><th>Unit</th><th>Equal unit split</th><th>Occupant-day split</th></tr></thead><tbody id="result"></tbody></table></div><p class="warning">Illustrative allocation only. Shared-meter utility billing can be restricted by state/local law and lease terms. Do not bill tenants based on this tool without confirming the applicable rules and written agreements.</p></section></div>''',r'''
const KEY='metersplit-v1';let units=localRead(KEY,[{name:'Unit A',people:3,days:31},{name:'Unit B',people:2,days:31}]);
function render(){window.currentRows=null;const start=$('start').value,end=$('end').value,bill=n('bill'),fixed=n('fixed'),days=dayDiff(start,end)+1;if(!start||!end||days<1||days>370||!nonneg(bill,fixed)||fixed>bill){$('status').textContent='Check dates, bill total and fixed charges (must not exceed total).';$('result').innerHTML='';return}
if(units.some(u=>u.days>days||u.people>100)){ $('status').textContent='Unit days must fit within the billing period and occupants must be at most 100.';$('result').innerHTML='';return }$('status').textContent='';$('total').textContent=usd(bill);$('days').textContent=days;let weight=units.reduce((s,u)=>s+u.people*u.days,0),num=units.length; if(!num||!weight){$('result').innerHTML='';$('status').textContent='Add at least one unit with positive occupants and days.';return}
let rows=units.map(u=>({name:u.name,equal:bill/num,weighted:fixed/num+(bill-fixed)*(u.people*u.days)/weight}));let er=0,wr=0;
$('result').innerHTML=rows.map((r,i)=>{let e=i===rows.length-1?Math.round(bill*100)/100-er:Math.round(r.equal*100)/100,w=i===rows.length-1?Math.round(bill*100)/100-wr:Math.round(r.weighted*100)/100;er+=e;wr+=w;return `<tr><td>${esc(r.name)}</td><td>${usd(e)}</td><td>${usd(w)}</td></tr>`}).join('')+`<tr><th>Total</th><th>${usd(er)}</th><th>${usd(wr)}</th></tr>`;
window.currentRows=rows;}
function paint(){ $('units').innerHTML=units.map((u,i)=>`<div class="row"><button data-remove="${i}" aria-label="Remove unit ${i+1}">Remove</button><div class="fields"><label>Unit name<input data-i="${i}" data-k="name" value="${esc(u.name)}" maxlength="55"></label><label>Occupants<input type="number" min="0" max="100" data-i="${i}" data-k="people" value="${u.people}"></label><label>Days in period<input type="number" min="0" max="370" data-i="${i}" data-k="days" value="${u.days}"></label></div></div>`).join('');render()}
$('units').addEventListener('input',e=>{if(!e.target.matches('[data-i]'))return;let i=+e.target.dataset.i,k=e.target.dataset.k;units[i][k]=k==='name'?e.target.value:Math.max(0,Number(e.target.value)||0);localWrite(KEY,units);render()});
$('units').addEventListener('click',e=>{let b=e.target.closest('[data-remove]');if(!b)return;units.splice(+b.dataset.remove,1);localWrite(KEY,units);paint()});
$('add').onclick=()=>{units.push({name:'Unit '+(units.length+1),people:1,days:Math.max(1,Math.min(31,dayDiff($('start').value,$('end').value)+1||30))});localWrite(KEY,units);paint()};
['start','end','bill','fixed'].forEach(id=>$(id).addEventListener('input',render));
$('export').onclick=()=>{render();if(!window.currentRows)return;download(csv([['unit','occupants','days','equal_split_usd','occupant_day_split_usd','bill_total_usd','fixed_base_usd','start','end'],...window.currentRows.map((r,i)=>[r.name,units[i].people,units[i].days,r.equal.toFixed(2),r.weighted.toFixed(2),n('bill'),n('fixed'),$('start').value,$('end').value])]),'shared-water-bill-split.csv')};paint();
''',r'''<h2>Understand the difference between two shared-meter allocations</h2><p>A single water meter may serve two rental units even when the number of occupants differs. MeterSplit shows two <em>hypothetical</em> approaches: equal amounts per unit, and a hybrid that splits fixed base charges equally while allocating the remaining bill in proportion to occupant-days. It does not claim that either method is fair, lawful or an estimate of actual consumption.</p><p>Enter the bill period, total and fixed charges, then add each unit's residents and days. Review both columns and export a CSV to discuss the assumptions. Actual utility usage varies by behavior and fixtures, and many jurisdictions require submetering, specific lease language or landlord-paid utilities. Consult your lease and local rules before collecting any amount.</p>''')

app(1,r'''<div class="grid"><section class="panel"><h2>Choose client delivery files</h2><label>Photos (JPG, PNG or WebP)<input id="files" type="file" multiple accept=".jpg,.jpeg,.png,.webp,image/jpeg,image/png,image/webp"></label><div class="fields" style="margin-top:15px"><label>Client / project prefix<input id="prefix" type="text" value="Smith-Wedding" maxlength="55"></label><label>Starting sequence<input id="startnum" type="number" min="1" max="999999" value="1"></label><label>Number padding<input id="pad" type="number" min="2" max="6" value="3"></label><label>Optional suffix<input id="suffix" type="text" placeholder="final" maxlength="35"></label></div><div class="actions"><button id="preview" class="primary">Preview names</button><button id="zip">Download renamed ZIP</button></div><p id="status" class="status" role="status"></p><p class="note">Local only. Files are not uploaded. Maximum 100 images / 120 MiB total. Original files are never changed.</p></section><section class="panel"><h2>Renaming preview</h2><div class="metrics"><div class="metric"><small>Images selected</small><strong id="count">0</strong></div><div class="metric"><small>Total size</small><strong id="size">0 MB</strong></div></div><div class="tablewrap"><table><thead><tr><th>Original</th><th>Client filename</th></tr></thead><tbody id="names"></tbody></table></div><p class="warning">This tool creates an uncompressed ZIP for broad compatibility; ZIP size may be similar to the source files. Browser memory limits apply. No cloud backup or delivery service.</p></section></div>''',r'''
let selected=[],mapped=[];const allowed=/\.(jpe?g|png|webp)$/i;
function plan(){selected=[...$('files').files];let total=selected.reduce((s,f)=>s+f.size,0);$('count').textContent=selected.length;$('size').textContent=(total/1048576).toFixed(1)+' MiB';mapped=[];
if(!selected.length||selected.length>100||total>120*1048576||selected.some(f=>!allowed.test(f.name))){$('status').textContent='Choose 1–100 JPG/PNG/WebP files totaling at most 120 MiB.';$('names').innerHTML='';return false}
let prefix=$('prefix').value.trim().replace(/[^a-zA-Z0-9_-]+/g,'-').replace(/^-+|-+$/g,'')||'client',suffix=$('suffix').value.trim().replace(/[^a-zA-Z0-9_-]+/g,'-').replace(/^-+|-+$/g,''),start=Number($('startnum').value),pad=Number($('pad').value);if(!Number.isInteger(start)||start<1||start>999999||!Number.isInteger(pad)||pad<2||pad>6){$('status').textContent='Check sequence and padding.';return false}
let seen=new Set();mapped=selected.map((f,i)=>{let ext=f.name.split('.').pop().toLowerCase(),base=`${prefix}_${String(start+i).padStart(pad,'0')}${suffix?'_'+suffix:''}`,name=base+'.'+ext; if(seen.has(name))throw Error('Duplicate generated filename');seen.add(name);return {file:f,name}});
$('names').innerHTML=mapped.map(x=>`<tr><td>${esc(x.file.name)}</td><td>${esc(x.name)}</td></tr>`).join('');$('status').textContent='Preview ready. Original files remain unchanged.';return true}
$('preview').onclick=()=>{try{plan()}catch(e){$('status').textContent=e.message}};
['files','prefix','suffix','startnum','pad'].forEach(id=>$(id).addEventListener('change',()=>{mapped=[];$('status').textContent='Settings changed — preview names again.'}));
function crc32(bytes){let c=0xffffffff;for(let b of bytes){c^=b;for(let j=0;j<8;j++)c=(c>>>1)^(c&1?0xedb88320:0)}return(c^0xffffffff)>>>0}
function le16(n){return[n&255,(n>>>8)&255]}function le32(n){return[n&255,(n>>>8)&255,(n>>>16)&255,(n>>>24)&255]}
async function zipBytes(items){const enc=new TextEncoder(),parts=[],central=[];let offset=0;for(const item of items){const data=new Uint8Array(await item.file.arrayBuffer()),name=enc.encode(item.name),crc=crc32(data),sz=data.length;
let head=new Uint8Array([...le32(0x04034b50),...le16(20),...le16(0x0800),...le16(0),...le16(0),...le16(0),...le32(crc),...le32(sz),...le32(sz),...le16(name.length),...le16(0),...name]);parts.push(head,data);
let c=new Uint8Array([...le32(0x02014b50),...le16(20),...le16(20),...le16(0x0800),...le16(0),...le16(0),...le16(0),...le32(crc),...le32(sz),...le32(sz),...le16(name.length),...le16(0),...le16(0),...le16(0),...le16(0),...le32(0),...le32(offset),...name]);central.push(c);offset+=head.length+sz}
let cdSize=central.reduce((s,x)=>s+x.length,0),end=new Uint8Array([...le32(0x06054b50),...le16(0),...le16(0),...le16(items.length),...le16(items.length),...le32(cdSize),...le32(offset),...le16(0)]);return new Blob([...parts,...central,end],{type:'application/zip'})}
$('zip').onclick=async()=>{try{if(!plan())return;$('zip').disabled=true;$('status').textContent='Building ZIP locally…';let blob=await zipBytes(mapped),url=URL.createObjectURL(blob),a=document.createElement('a');a.href=url;a.download='client-renamed-photos.zip';document.body.appendChild(a);a.click();a.remove();setTimeout(()=>URL.revokeObjectURL(url),10000);$('status').textContent='ZIP generated. Verify filenames after download.'}catch(e){$('status').textContent='ZIP failed: '+e.message}finally{$('zip').disabled=false}};
''',r'''<h2>Make client filenames readable without uploading originals</h2><p>Camera files often arrive with technical names such as DSC_1234.jpg. A consistent delivery name can include the client or project and a padded sequence number. ClientRename previews the new names before creating a ZIP containing renamed copies. The original files on your computer or phone are never renamed.</p><p>This lightweight tool deliberately avoids image editing, watermarking and metadata changes. It is not a replacement for a full photo catalog. Select no more than 100 JPEG, PNG or WebP files, confirm the sequence and download one ZIP. Files stay inside the browser tab; export promptly because the tool does not store a gallery or keep backups. For very large RAW batches, use desktop photo-management software instead.</p>''')

app(2,r'''<div class="grid"><section class="panel"><h2>Cost of a small service visit</h2><div class="fields">
<label>Drive time, round trip (minutes)<input id="drive" type="number" min="0" value="45"></label><label>On-site labor (minutes)<input id="onsite" type="number" min="0" value="40"></label>
<label>Target labor compensation ($/hour)<input id="labor" type="number" min="0" value="65"></label><label>Truck / fuel per visit ($)<input id="truck" type="number" min="0" value="18"></label>
<label>Materials / consumables ($)<input id="material" type="number" min="0" value="12"></label><label>Allocated overhead per visit ($)<input id="overhead" type="number" min="0" value="24"></label>
<label>Target margin (%)<input id="margin" type="number" min="0" max="90" value="25"></label><label>Your existing minimum ($)<input id="current" type="number" min="0" value="125"></label>
<label>Job description<input id="job" type="text" value="Replace bathroom faucet" maxlength="90"></label></div><div class="actions"><button id="copy" class="primary">Copy customer quote</button><button id="export">Export pricing CSV</button><button id="print">Print estimate</button></div><p id="status" class="status" role="status"></p></section><section class="panel"><h2>Recommended minimum</h2><div class="metrics"><div class="metric"><small>Estimated cost floor</small><strong id="cost">$0</strong></div><div class="metric"><small>Price at target margin</small><strong id="price">$0</strong></div><div class="metric"><small>Charge after your minimum</small><strong id="charge">$0</strong></div><div class="metric"><small>Actual margin at charge</small><strong id="actual">0%</strong></div></div><p class="note" id="breakdown"></p><p class="warning">This is a business planning estimate, not an industry price benchmark. Confirm taxes, insurance, licenses, materials and your real hourly cost. Customer quotes should describe scope and exclusions.</p></section></div>''',r'''
let result={};function render(){let v=['drive','onsite','labor','truck','material','overhead','margin','current'].map(n);if(!nonneg(...v)||v[6]>=100){$('status').textContent='Use nonnegative values and a margin below 100%.';return}let[drive,onsite,labor,truck,material,overhead,margin,current]=v,cost=(drive+onsite)/60*labor+truck+material+overhead,price=cost/(1-margin/100),charge=Math.max(price,current),actual=charge?(charge-cost)/charge*100:0;result={cost,price,charge,actual,drive,onsite,labor,truck,material,overhead,margin,current};$('cost').textContent=usd(cost);$('price').textContent=usd(price);$('charge').textContent=usd(charge);$('actual').textContent=actual.toFixed(1)+'%';$('breakdown').textContent=`${(drive+onsite).toFixed(0)} total minutes, including ${drive} driving. Margin means profit ÷ price, not markup on cost.`;$('status').textContent='';}
['drive','onsite','labor','truck','material','overhead','margin','current'].forEach(id=>$(id).oninput=render);
$('copy').onclick=async()=>{render();let t=`Estimate for ${$('job').value.trim()||'service visit'}: ${usd(result.charge)} minimum for the described visit. Additional work, unforeseen materials and applicable taxes are quoted separately. Subject to final scope confirmation.`;try{await navigator.clipboard.writeText(t);$('status').textContent='Quote copied.'}catch{$('status').textContent='Clipboard unavailable. Use print or CSV.'}};
$('export').onclick=()=>{render();download(csv([['job','drive_minutes','onsite_minutes','labor_rate','truck_cost','materials','overhead','target_margin_pct','cost_floor','price_at_margin','quoted_minimum'],[$('job').value,result.drive,result.onsite,result.labor,result.truck,result.material,result.overhead,result.margin,result.cost.toFixed(2),result.price.toFixed(2),result.charge.toFixed(2)]]),'handyman-minimum-visit-price.csv')};$('print').onclick=()=>{render();window.print()};render();
''',r'''<h2>Why a 20-minute repair can require a higher service-call minimum</h2><p>A small repair still requires travel, vehicle expenses, scheduling and administration. VisitFloor combines round-trip drive time with on-site labor, materials and overhead, then calculates a minimum price using your chosen margin. It also compares that price with the minimum you already advertise.</p><p>For example, if a job requires 45 minutes of driving and 40 minutes on site, charging only for the on-site minutes may understate the visit's cost. Enter your own numbers; this tool does not recommend market rates or guarantee profitability. The customer-facing quote intentionally avoids exposing internal hourly compensation or markup. Check licensing, tax and warranty obligations separately before accepting work.</p>''')

app(3,r'''<div class="grid"><section class="panel"><h2>Compare rush pricing approaches</h2><div class="fields">
<label>Client / project<input id="project" type="text" value="Landing page update" maxlength="90"></label><label>Standard project fee ($)<input id="base" type="number" min="0" value="1200"></label>
<label>Normal turnaround (days)<input id="normal" type="number" min="1" value="7"></label><label>Requested turnaround (days)<input id="rush" type="number" min="1" value="2"></label>
<label>Proposed rush premium (%)<input id="premium" type="number" min="0" value="30"></label><label>Extra out-of-hours effort (hours)<input id="extra" type="number" min="0" value="5"></label>
<label>Extra-hour cost ($/hour)<input id="hourly" type="number" min="0" value="65"></label><label>Target contribution margin (%)<input id="margin" type="number" min="0" max="90" value="25"></label></div><div class="actions"><button id="copy" class="primary">Copy rush quote</button><button id="export">Export comparison CSV</button></div><p id="status" class="status" role="status"></p></section><section class="panel"><h2>Quote comparison</h2><div class="metrics"><div class="metric"><small>Time compressed by</small><strong id="compress">0%</strong></div><div class="metric"><small>Percentage premium quote</small><strong id="percent">$0</strong></div><div class="metric"><small>Overtime-cost quote</small><strong id="overtime">$0</strong></div><div class="metric"><small>Higher of the two</small><strong id="suggested">$0</strong></div></div><p id="logic" class="note"></p><p class="warning">A rush fee is a proposal, not a standard or entitlement. Confirm feasibility, availability and any contractual approval before accepting. This tool does not send an invoice or bind the client.</p></section></div>''',r'''
let r={};function render(){let v=['base','normal','rush','premium','extra','hourly','margin'].map(n);if(!nonneg(...v)||v[1]<1||v[2]<1||v[6]>=100){$('status').textContent='Check dates, fees and margin (must be below 100%).';return}let[base,normal,rush,premium,extra,hourly,margin]=v,compressed=Math.max(0,100*(1-rush/normal)),percent=base*(1+premium/100),overtime=base+extra*hourly/(1-margin/100),suggested=Math.max(percent,overtime);r={base,normal,rush,premium,extra,hourly,margin,compressed,percent,overtime,suggested};$('compress').textContent=compressed.toFixed(1)+'%';$('percent').textContent=usd(percent);$('overtime').textContent=usd(overtime);$('suggested').textContent=usd(suggested);$('logic').textContent=`Premium approach adds ${usd(percent-base)}. Overtime approach adds ${usd(overtime-base)} to cover extra effort at your target margin. Neither approach guarantees that a ${rush}-day deadline is achievable.`;$('status').textContent='';}
['base','normal','rush','premium','extra','hourly','margin'].forEach(id=>$(id).oninput=render);
$('copy').onclick=async()=>{render();let t=`Rush delivery option — ${$('project').value.trim()||'project'}\nStandard scope: ${usd(r.base)} with ${r.normal}-day turnaround.\nRequested expedited turnaround: ${r.rush} days.\nProposed expedited price: ${usd(r.suggested)} (additional ${usd(r.suggested-r.base)}).\nThis offer is subject to schedule availability, agreed scope, and written acceptance before work begins.`;try{await navigator.clipboard.writeText(t);$('status').textContent='Quote copied.'}catch{$('status').textContent='Clipboard unavailable. Use CSV.'}};
$('export').onclick=()=>{render();download(csv([['project','standard_fee','standard_days','rush_days','rush_premium_pct','extra_hours','hour_cost','target_margin_pct','percent_quote','overtime_quote','proposed_quote'],[$('project').value,r.base,r.normal,r.rush,r.premium,r.extra,r.hourly,r.margin,r.percent.toFixed(2),r.overtime.toFixed(2),r.suggested.toFixed(2)]]),'freelance-rush-fee-comparison.csv')};render();
''',r'''<h2>Make rush work an explicit pricing decision</h2><p>Freelancers often accept last-minute changes without considering overtime, displaced client work or the practical cost of a compressed deadline. RushQuote shows two alternative methods: a percentage premium on the original project fee, and a cost-based premium for additional out-of-hours work at a chosen margin.</p><p>The larger number is displayed for comparison, not as a mandated charge. You still need to confirm whether the deadline is realistic and whether the original contract permits an expedited fee. Use the copyable quote to propose a specific amount, turnaround and approval condition. For recurring retainers, agree on an urgent-request policy before the next emergency.</p>''')

app(4,r'''<div class="grid"><section class="panel"><h2>Property appliance inventory</h2><div class="fields"><label>Property / unit<input id="property" type="text" value="Maple Duplex A" maxlength="65"></label><label>Appliance<input id="appliance" type="text" value="Refrigerator" maxlength="60"></label><label>Brand / model<input id="model" type="text" value="Sample model" maxlength="65"></label><label>Serial number (optional)<input id="serial" type="text" maxlength="65"></label><label>Purchase / install date<input id="purchased" type="date" value="2025-11-01"></label><label>Warranty term (months)<input id="months" type="number" min="1" max="240" value="24"></label><label>Reminder before expiry (days)<input id="reminder" type="number" min="1" max="365" value="30"></label></div><div class="actions"><button id="add" class="primary">Save appliance</button><button id="csv">Export inventory CSV</button><button id="ics">Download reminder calendar</button></div><p id="status" class="status" role="status"></p><div id="records"></div></section><section class="panel"><h2>Warranty overview</h2><div class="metrics"><div class="metric"><small>Appliances tracked</small><strong id="count">0</strong></div><div class="metric"><small>Expired</small><strong id="expired">0</strong></div><div class="metric"><small>Expiring within 90 days</small><strong id="soon">0</strong></div><div class="metric"><small>Active beyond 90 days</small><strong id="active">0</strong></div></div><p class="warning">Warranty dates are estimates based on the term you enter. Coverage can depend on registration, labor exclusions, proof of purchase and manufacturer policy. No email or push reminders are sent; import the ICS file into your calendar and confirm the events.</p></section></div>''',r'''
const KEY='warrantynest-v1';let entries=localRead(KEY,[]);function plusMonths(date,m){let d=new Date(date+'T12:00:00Z'),day=d.getUTCDate();d.setUTCDate(1);d.setUTCMonth(d.getUTCMonth()+m);let max=new Date(Date.UTC(d.getUTCFullYear(),d.getUTCMonth()+1,0)).getUTCDate();d.setUTCDate(Math.min(day,max));return d.toISOString().slice(0,10)}
function isoBasic(date){return date.replaceAll('-','')}
function render(){let today=new Date().toISOString().slice(0,10),expired=0,soon=0,active=0;let ordered=entries.map((x,i)=>({...x,i,expiry:plusMonths(x.purchased,x.months)})).sort((a,b)=>a.expiry.localeCompare(b.expiry));
$('records').innerHTML=ordered.map(x=>{let left=dayDiff(today,x.expiry);if(left<0)expired++;else if(left<=90)soon++;else active++;return `<div class="row"><button data-remove="${x.i}">Remove</button><strong>${esc(x.appliance)} · ${esc(x.property)}</strong><small>${esc(x.model)}${x.serial?' · S/N '+esc(x.serial):''}<br>Expires ${x.expiry} · <span class="${left<0?'bad':'good'}">${left<0?'Expired '+Math.abs(left)+' days ago':left+' days left'}</span></small></div>`}).join('')||'<p class="note">No appliance records yet. Add one above to create a local inventory.</p>';
$('count').textContent=entries.length;$('expired').textContent=expired;$('soon').textContent=soon;$('active').textContent=active;}
$('add').onclick=()=>{let property=$('property').value.trim(),appliance=$('appliance').value.trim(),purchased=$('purchased').value,months=n('months'),reminder=n('reminder');if(!property||!appliance||!purchased||!Number.isInteger(months)||months<1||months>240||!Number.isInteger(reminder)||reminder<1||reminder>365){$('status').textContent='Complete property, appliance, purchase date, warranty months and reminder days.';return}entries.push({property,appliance,model:$('model').value.trim(),serial:$('serial').value.trim(),purchased,months,reminder});localWrite(KEY,entries);render();$('status').textContent='Saved on this device only.'};
$('records').onclick=e=>{let b=e.target.closest('[data-remove]');if(!b)return;entries.splice(+b.dataset.remove,1);localWrite(KEY,entries);render()};
$('csv').onclick=()=>download(csv([['property','appliance','model','serial','purchase_date','warranty_months','expiry_date','reminder_days'],...entries.map(x=>[x.property,x.appliance,x.model,x.serial,x.purchased,x.months,plusMonths(x.purchased,x.months),x.reminder])]),'rental-appliance-warranty-inventory.csv');
$('ics').onclick=()=>{if(!entries.length){$('status').textContent='Add an appliance before exporting calendar reminders.';return}let now=new Date().toISOString().replace(/[-:]/g,'').replace(/\.\d+Z$/,'Z');let lines=['BEGIN:VCALENDAR','VERSION:2.0','PRODID:-//Worklane Tools//WarrantyNest//EN','CALSCALE:GREGORIAN','METHOD:PUBLISH'];function icsEsc(s){return String(s).replaceAll('\\','\\\\').replaceAll(',','\\,').replaceAll(';','\\;').replaceAll('\n','\\n')}
entries.forEach((x,i)=>{let expiry=plusMonths(x.purchased,x.months),d=new Date(expiry+'T12:00:00Z');d.setUTCDate(d.getUTCDate()-x.reminder);let reminderDate=d.toISOString().slice(0,10);lines.push('BEGIN:VEVENT','UID:warrantynest-'+i+'-'+isoBasic(expiry)+'@worklane.local','DTSTAMP:'+now,'DTSTART;VALUE=DATE:'+isoBasic(reminderDate),'DTEND;VALUE=DATE:'+isoBasic(new Date(Date.parse(reminderDate+'T12:00:00Z')+86400000).toISOString().slice(0,10)),'SUMMARY:'+icsEsc('Check warranty: '+x.appliance+' — '+x.property),'DESCRIPTION:'+icsEsc('Warranty estimated to expire '+expiry+'. Check terms, proof of purchase and registration.'),'END:VEVENT')});lines.push('END:VCALENDAR');download(lines.join('\r\n')+'\r\n','appliance-warranty-reminders.ics','text/calendar;charset=utf-8');$('status').textContent='Calendar file generated; verify reminders after import.'};render();
''',r'''<h2>Know which rental appliance warranty may still apply</h2><p>When a refrigerator or HVAC component fails, a landlord may need the model, serial number, installation date and warranty documents before contacting a service technician. WarrantyNest keeps a simple appliance-by-property inventory in this browser and calculates an estimated expiration date from the purchase date and warranty term you enter.</p><p>Export a CSV for independent backup or an ICS calendar file for manual import into your preferred calendar. Calendar events are reminders to check coverage, not proof of warranty validity. Manufacturers may have different coverage for parts and labor or require timely registration. This MVP does not upload receipts, sync across devices or send notifications. Keep the original documents somewhere safe.</p>''')
